import {describe,it,expect} from "vitest";
import net from "net";
import {probeMinecraft,inspectNetwork} from "../nomad_network";
import {validateIngress,formatEndpoint,frpConfiguration} from "../nomad_ingress";
const profile={kind:"frp",bindHost:"127.0.0.1",bindPort:25565,publicHost:"localhost",publicPort:30065,family:"auto",tunnelHost:"edge.example.com",tunnelPort:7000};
function vint(value:number){const b=[];do{let n=value&127;value>>>=7;if(value)n|=128;b.push(n);}while(value);return Buffer.from(b);}
async function fixture(response?:Buffer,ipv6:boolean|string=false){const server=net.createServer(socket=>{socket.once("data",()=>{if(response){socket.write(response.subarray(0,2));setTimeout(()=>socket.end(response.subarray(2)),5);}});socket.on("error",()=>{});});await new Promise<void>((resolve,reject)=>{server.once("error",reject);server.listen(0,typeof ipv6==="string"?ipv6:ipv6?"::1":"127.0.0.1",resolve);});return {server,port:(server.address() as net.AddressInfo).port,close:()=>new Promise<void>(r=>server.close(()=>r()))};}
describe("network profiles and bounded protocol self-check",()=>{
 it("separates frp control, bind and advertised ports including IPv6 formatting",()=>{const saved=validateIngress(profile);expect(frpConfiguration(saved,"room")).toContain("serverPort = 7000");expect(frpConfiguration(saved,"room")).toContain("localPort = 25565");expect(frpConfiguration(saved,"room")).toContain("remotePort = 30065");expect(formatEndpoint("::1",25565)).toBe("[::1]:25565");expect(()=>validateIngress({...profile,publicHost:"http://localhost"})).toThrow();expect(()=>validateIngress({...profile,bindHost:"example.com"})).toThrow();expect(()=>validateIngress({...profile,publicHost:"0.0.0.0"})).toThrow();});
 it("recognizes a fragmented real TCP Minecraft status without claiming public verification",async()=>{const json=Buffer.from(JSON.stringify({version:{name:"Probe",protocol:763}})),body=Buffer.concat([Buffer.from([0]),vint(json.length),json]),f=await fixture(Buffer.concat([vint(body.length),body]));try{expect((await probeMinecraft("127.0.0.1",f.port,"localhost")).protocol).toBe(763);const report=await inspectNetwork(validateIngress({...profile,publicHost:"127.0.0.1",publicPort:f.port}),{active:true,address:"127.0.0.1:"+f.port,ready:true,slots:1});expect(report.checks.find(c=>c.key==="minecraft")?.status).toBe("ok");expect(report.publicReachability).toBe("unverified");expect(report.checks.find(c=>c.key==="external")?.status).toBe("unverified");}finally{await f.close();}});
 it("probes a real IPv6 loopback endpoint and formats the advertised address",async()=>{const json=Buffer.from(JSON.stringify({version:{name:"IPv6 Probe",protocol:763}})),body=Buffer.concat([Buffer.from([0]),vint(json.length),json]),f=await fixture(Buffer.concat([vint(body.length),body]),true);try{const report=await inspectNetwork(validateIngress({...profile,bindHost:"::1",publicHost:"::1",publicPort:f.port,family:"ipv6"}),{active:true,address:"[::1]:"+f.port,ready:true,slots:1});expect(report.checks.find(c=>c.key==="minecraft")?.status).toBe("ok");expect(report.checks.find(c=>c.key==="minecraft")?.family).toBe(6);expect(report.checks.find(c=>c.key==="minecraft")?.address).toBe("[::1]:"+f.port);}finally{await f.close();}});
 it("does not label HTTP as Minecraft and bounds a silent endpoint",async()=>{const f=await fixture(Buffer.from("HTTP/1.1 200 OK\r\n\r\n"));try{await expect(probeMinecraft("127.0.0.1",f.port,"localhost",200)).rejects.toThrow();}finally{await f.close();}const silent=await fixture();try{await expect(probeMinecraft("127.0.0.1",silent.port,"localhost",80)).rejects.toThrow("connection_timeout");}finally{await silent.close();}});
 it("accepts IPv4 and IPv6 through one wildcard dual-stack TCP listener",async()=>{const json=Buffer.from(JSON.stringify({version:{name:"Dual stack",protocol:763}})),body=Buffer.concat([Buffer.from([0]),vint(json.length),json]),f=await fixture(Buffer.concat([vint(body.length),body]),"::");try{expect((await probeMinecraft("127.0.0.1",f.port,"localhost")).protocol).toBe(763);expect((await probeMinecraft("::1",f.port,"localhost")).protocol).toBe(763);}finally{await f.close();}});
 it("marks missing profiles and idle rooms as unverified",async()=>{const report=await inspectNetwork(undefined,{active:false,address:null,ready:false,slots:0});expect(report.checks.find(c=>c.key==="listener")?.status).toBe("unverified");expect(report.checks.find(c=>c.key==="profile")?.message).toBe("network_profile_missing");});
});
